potapovQuest.scripts:
QUEST_EVENT_TYPE = globals().get('QUEST_EVENT_TYPE')
""":type: quest_definitions.QUEST_EVENT_TYPE"""

quest_progress = globals().get('quest_progress')
""":type: quest_progress"""

MAIN_PROGRESS_TOP_BY_KILLS = 'topByKills'
MAIN_PROGRESS_HITS_FREQUENCY = 'hitsFrequency'
MAIN_PROGRESS_SERIES = 'battlesSeries'

def onInit(eventType, eventData, quest, processor):
    for event in events.iterkeys():
        processor.subscribe(event, quest)
    return True

def onFinishBattle(eventType, eventData, quest, processor):
    questProgress = quest_progress.BaseQuestProgress(quest.config, processor.getQuestProgress(quest.progressID))

    shots = eventData['avatarResults']['shots']
    if shots:
        killsPosition = eventData['avatarResults']['misc']['max']['kills']
        if killsPosition <= questProgress.getProgress(MAIN_PROGRESS_TOP_BY_KILLS).getParam('desiredPosition'):
            hitsFrequency = eventData['avatarResults']['enemyHits'] * 100. / shots
            questProgress.increaseSeriesUntilComplete(MAIN_PROGRESS_SERIES, MAIN_PROGRESS_HITS_FREQUENCY, hitsFrequency)

    eventData['results'].update(processor.checkComplete(questProgress, quest.progressID))
    processor.setQuestProgress(quest.progressID, questProgress.save())

events = {
    QUEST_EVENT_TYPE.INIT: onInit,
    QUEST_EVENT_TYPE.FINISH_BATTLE: onFinishBattle,
}

def quest(eventType, eventData, quest, processor):
    LOG('QUEST EVENT:', eventType, quest.id)
    return events.get(eventType, lambda *args: False)(eventType, eventData, quest, processor)
